      <svg class="ic st-light" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4.5"/><path d="M12 2v2M12 20v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M2 12h2M20 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/></svg>
      <span class="st-dark">Dark stage</span><span class="st-light">Light stage</span>
    </button>
    <button type="button" class="fb-toggle motion-toggle" id="motionToggle" aria-pressed="false" aria-label="Pause all asset animations">
      <svg class="ic mt-pause" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>
      <svg class="ic mt-play" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 5l12 7-12 7z"/></svg>
      <span class="mt-pause">Pause motion</span><span class="mt-play">Play motion</span>
    </button>
    <button type="button" class="fb-toggle reduce-toggle" id="reduceToggle" aria-pressed="false" aria-label="Preview the reduced-motion fallback">
      <svg class="ic rm-on" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="3.6" r="1.4"/><path d="M5 8c2.4 1.1 4.5 1.4 7 1.4S16.6 9.1 19 8"/><path d="M12 9.4v5.2"/><path d="M8.6 21l3.4-6 3.4 6"/></svg>
      <svg class="ic rm-off" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12h4l3 8 4-16 3 8h4"/></svg>
