  <div class="grid">

    <!-- 1. EMPTY STATE -->
    <article class="card" data-cat="onboarding" style="--c:var(--calm)">
      <div class="stage">
        <svg viewBox="0 0 120 120" role="img" aria-label="Friendly empty box illustration">
          <g class="a-float">
